    test("dependabotListAlertsForEnterprise answers 403 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/403';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_18.dependabotListAlertsForEnterprise(
        config,
        enterprise: (jsonDecode("\"enterprise\"") as String),
        classification: SdkPresent<String>((jsonDecode("\"classification\"") as String)),
        state: SdkPresent<String>((jsonDecode("\"state\"") as String)),
        severity: SdkPresent<String>((jsonDecode("\"severity\"") as String)),
        ecosystem: SdkPresent<String>((jsonDecode("\"ecosystem\"") as String)),
        package: SdkPresent<String>((jsonDecode("\"package\"") as String)),
        epssPercentage: SdkPresent<String>((jsonDecode("\"epss_percentage\"") as String)),
        has: SdkPresent<dynamic>(jsonDecode("\"has\"")),
        assignee: SdkPresent<String>((jsonDecode("\"assignee\"") as String)),
        scope: SdkPresent<SchemaSchemaa304fedd>(SchemaSchemaa304fedd.fromJson(jsonDecode("\"development\"") as String)),
        relationship: SdkPresent<String>((jsonDecode("\"relationship\"") as String)),
        sort: SdkPresent<SchemaSchemab6482dba>(SchemaSchemab6482dba.fromJson(jsonDecode("\"created\"") as String)),
        direction: SdkPresent<SchemaSchema0df64690>(SchemaSchema0df64690.fromJson(jsonDecode("\"desc\"") as String)),
        before: SdkPresent<String>((jsonDecode("\"before\"") as String)),
        after: SdkPresent<String>((jsonDecode("\"after\"") as String)),
        perPage: SdkPresent<int>((jsonDecode("30") as num).toInt()),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 403);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"message\":\"example text\",\"documentation_url\":\"https://example.com\",\"url\":\"https://example.com\",\"status\":\"active\"}")),
        isNull,
      );
    });

