    test("gistsCheckIsStarred reaches the mock and decodes its response", () async {
      await sdk_methods_21.gistsCheckIsStarred(
        config,
        gistId: (jsonDecode("\"gist-1\"") as String),
      );
    });

    test("gistsCheckIsStarred answers 403 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/403';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_21.gistsCheckIsStarred(
        config,
        gistId: (jsonDecode("\"gist-1\"") as String),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 403);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"message\":\"example text\",\"documentation_url\":\"https://example.com\",\"url\":\"https://example.com\",\"status\":\"active\"}")),
        isNull,
      );
    });

    test("gistsCreate reaches the mock and decodes its response", () async {
      final actual = await sdk_methods_21.gistsCreate(
        config,
        files: (jsonDecode("{\"README.md\":{\"content\":\"Hello World\"}}") as Map).map((key, value) => MapEntry((key as String), GistsCreateRequestBodyFilesValue.fromJson((value as Map).cast<String, dynamic>()))),
        description: SdkPresent<String>((jsonDecode("\"Example of a gist\"") as String)),
        public: SdkPresent<dynamic>(jsonDecode("false")),
      );
      expect(
