    test("issuesListForOrg answers 404 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/404';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_26.issuesListForOrg(
        config,
        org: (jsonDecode("\"org\"") as String),
        filter: SdkPresent<IssuesListForOrgFilter>(IssuesListForOrgFilter.fromJson(jsonDecode("\"assigned\"") as String)),
        state: SdkPresent<IssuesListForOrgState>(IssuesListForOrgState.fromJson(jsonDecode("\"open\"") as String)),
        labels: SdkPresent<String>((jsonDecode("\"labels\"") as String)),
        type_: SdkPresent<String>((jsonDecode("\"type\"") as String)),
        sort: SdkPresent<IssuesListForOrgSort>(IssuesListForOrgSort.fromJson(jsonDecode("\"created\"") as String)),
        direction: SdkPresent<SchemaSchema0df64690>(SchemaSchema0df64690.fromJson(jsonDecode("\"desc\"") as String)),
        since: SdkPresent<String>((jsonDecode("\"2024-01-01T00:00:00Z\"") as String)),
        perPage: SdkPresent<int>((jsonDecode("30") as num).toInt()),
        page: SdkPresent<int>((jsonDecode("1") as num).toInt()),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 404);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"message\":\"example text\",\"documentation_url\":\"https://example.com\",\"url\":\"https://example.com\",\"status\":\"active\"}")),
        isNull,
      );
    });

