    test("projectsUpdateItemForOrg answers 401 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/401';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_34.projectsUpdateItemForOrg(
        config,
        projectNumber: (jsonDecode("1") as num).toInt(),
        org: (jsonDecode("\"org\"") as String),
        itemId: (jsonDecode("1") as num).toInt(),
        fields: (jsonDecode("[{\"id\":123,\"value\":\"Updated text value\"}]") as List).map((element) => ProjectsUpdateItemForOrgRequestBodyFieldsItem.fromJson((element as Map).cast<String, dynamic>())).toList(),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 401);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"message\":\"example text\",\"documentation_url\":\"https://example.com\",\"url\":\"https://example.com\",\"status\":\"active\"}")),
        isNull,
      );
    });

