    test("reposListForks answers 400 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/400';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_38.reposListForks(
        config,
        owner: (jsonDecode("\"owner\"") as String),
        repo: (jsonDecode("\"repo\"") as String),
        sort: SdkPresent<ReposListForksSort>(ReposListForksSort.fromJson(jsonDecode("\"newest\"") as String)),
        perPage: SdkPresent<int>((jsonDecode("30") as num).toInt()),
        page: SdkPresent<int>((jsonDecode("1") as num).toInt()),
