    test("reposListInvitationsForAuthenticatedUser answers 401 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/401';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_38.reposListInvitationsForAuthenticatedUser(
        config,
        perPage: SdkPresent<int>((jsonDecode("30") as num).toInt()),
        page: SdkPresent<int>((jsonDecode("1") as num).toInt()),
